-- AI/ML pathway ("Cipher Division") Act 31 -- "Agentic AI" content.
-- Arc VI, Acts 28-33 (this Act does not close the Arc; Act 33 does).
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue_lines -> objectives ->
-- challenges -> hints pattern as every other pathway Act.
-- Only inserts into campaigns/operations/missions/dialogue_lines/objectives/
-- challenges/hints. The world-ai-agentic-ai row already exists.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-ai-agentic-ai', 'world-ai-agentic-ai', 'agentic-ai', '31A - Agentic AI', 'Turn a passive retriever into an active investigator -- tool calling, the model loop, the ReAct pattern, deterministic routing, planner/executor and evaluator/optimizer designs, parallel work, memory, state, and the termination budgets that keep an agent from running forever.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-ai-agentic-ai-1', 'campaign-ai-agentic-ai', 'the-reasoning-loop', 'The Reasoning Loop', 'What turns a single tool call into a real agent -- the model loop, tool descriptions, the ReAct pattern, deterministic routing, and planner/executor and evaluator/optimizer designs.', 1),
  ('operation-ai-agentic-ai-2', 'campaign-ai-agentic-ai', 'knowing-when-to-stop', 'Knowing When to Stop', 'Running agents safely -- parallel work, memory, state, termination budgets -- and the first real agent that never learned when to quit.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-ai-agentic-ai-01', 'world-ai-agentic-ai', 'campaign-ai-agentic-ai', 'operation-ai-agentic-ai-1', 'tool-calling-vs-agents', 'Tool Calling vs Agents', 'A poisoned archive means Cipher Division cannot fully trust its own memory anymore. The next tool needs to do more than retrieve -- it needs to actively investigate.', 'beginner', ARRAY['maya','elena','noah'], null, null, '{"type":"simulation","simulationId":"tool-calling-vs-agents-sim"}'::jsonb, '{"xp":670,"credits":180}'::jsonb, false, 1),
  ('mission-ai-agentic-ai-02', 'world-ai-agentic-ai', 'campaign-ai-agentic-ai', 'operation-ai-agentic-ai-1', 'model-loop', 'Model Loop', 'A single tool call answers one question. The model loop is what lets a system decide it needs to ask another one, using what it just learned.', 'beginner', ARRAY['elena','noah'], '{"requiredMissionIds":["mission-ai-agentic-ai-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"model-loop-sim"}'::jsonb, '{"xp":680,"credits":180}'::jsonb, false, 2),
  ('mission-ai-agentic-ai-03', 'world-ai-agentic-ai', 'campaign-ai-agentic-ai', 'operation-ai-agentic-ai-1', 'tool-descriptions', 'Tool Descriptions', 'An agent can only use a tool as well as it understands what that tool actually does. A vague description is not a small problem -- it is the whole problem.', 'beginner', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-agentic-ai-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"tool-descriptions-sim"}'::jsonb, '{"xp":680,"credits":185}'::jsonb, false, 3),
  ('mission-ai-agentic-ai-04', 'world-ai-agentic-ai', 'campaign-ai-agentic-ai', 'operation-ai-agentic-ai-1', 'react', 'ReAct', 'Thought, action, observation, repeat. ReAct is what happens when reasoning and acting stop being separate steps and become one running loop.', 'intermediate', ARRAY['elena','noah'], '{"requiredMissionIds":["mission-ai-agentic-ai-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"react-pattern-sim"}'::jsonb, '{"xp":690,"credits":185}'::jsonb, false, 4),
  ('mission-ai-agentic-ai-05', 'world-ai-agentic-ai', 'campaign-ai-agentic-ai', 'operation-ai-agentic-ai-1', 'deterministic-routing', 'Deterministic Routing', 'Not every decision needs a model to make it. Deterministic routing is what keeps the cheap, predictable choices out of the reasoning loop entirely.', 'intermediate', ARRAY['noah','elena'], '{"requiredMissionIds":["mission-ai-agentic-ai-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"deterministic-routing-sim"}'::jsonb, '{"xp":690,"credits":185}'::jsonb, false, 5),
  ('mission-ai-agentic-ai-06', 'world-ai-agentic-ai', 'campaign-ai-agentic-ai', 'operation-ai-agentic-ai-1', 'planner-executor', 'Planner/Executor', 'One model can plan the whole investigation up front. A separate model, or the same one wearing a different hat, actually carries each step out.', 'intermediate', ARRAY['elena','noah'], '{"requiredMissionIds":["mission-ai-agentic-ai-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"planner-executor-sim"}'::jsonb, '{"xp":700,"credits":190}'::jsonb, false, 6),
  ('mission-ai-agentic-ai-07', 'world-ai-agentic-ai', 'campaign-ai-agentic-ai', 'operation-ai-agentic-ai-2', 'evaluator-optimizer', 'Evaluator/Optimizer', 'A plan carried out is not the same as a plan carried out well. The evaluator/optimizer pattern is a second pass built to tell the difference.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-agentic-ai-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"evaluator-optimizer-sim"}'::jsonb, '{"xp":700,"credits":190}'::jsonb, false, 7),
  ('mission-ai-agentic-ai-08', 'world-ai-agentic-ai', 'campaign-ai-agentic-ai', 'operation-ai-agentic-ai-2', 'parallel-work', 'Parallel Work', 'Some steps in an investigation do not depend on each other at all. Running them one after another is not caution -- it is just wasted time.', 'intermediate', ARRAY['noah','elena'], '{"requiredMissionIds":["mission-ai-agentic-ai-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"parallel-work-sim"}'::jsonb, '{"xp":710,"credits":190}'::jsonb, false, 8),
  ('mission-ai-agentic-ai-09', 'world-ai-agentic-ai', 'campaign-ai-agentic-ai', 'operation-ai-agentic-ai-2', 'memory', 'Memory', 'An agent that forgets what it already tried is doomed to try it again. Memory is what lets a running investigation actually build on itself.', 'intermediate', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-agentic-ai-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"agent-memory-sim"}'::jsonb, '{"xp":710,"credits":195}'::jsonb, false, 9),
  ('mission-ai-agentic-ai-10', 'world-ai-agentic-ai', 'campaign-ai-agentic-ai', 'operation-ai-agentic-ai-2', 'state', 'State', 'Memory is what an agent remembers. State is the exact structure that tracks where an investigation stands, right now, at this exact step.', 'intermediate', ARRAY['noah','elena'], '{"requiredMissionIds":["mission-ai-agentic-ai-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"agent-state-sim"}'::jsonb, '{"xp":720,"credits":195}'::jsonb, false, 10),
  ('mission-ai-agentic-ai-11', 'world-ai-agentic-ai', 'campaign-ai-agentic-ai', 'operation-ai-agentic-ai-2', 'termination-budgets', 'Termination/Budgets', 'Every loop needs an exit. Without a termination condition or a hard budget, an agent has no way to ever decide that it is actually done.', 'intermediate', ARRAY['noah','elena'], '{"requiredMissionIds":["mission-ai-agentic-ai-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"termination-budgets-sim"}'::jsonb, '{"xp":720,"credits":195}'::jsonb, false, 11),
  ('mission-ai-agentic-ai-12', 'world-ai-agentic-ai', 'campaign-ai-agentic-ai', 'operation-ai-agentic-ai-2', 'the-infinite-loop', 'The Infinite Loop', 'Cipher Division''s first real investigative agent goes to work on the tampered archive records -- and does not stop, because nobody ever told it how.', 'boss', ARRAY['maya','elena','noah'], '{"requiredMissionIds":["mission-ai-agentic-ai-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"infinite-loop-boss-sim"}'::jsonb, '{"xp":1550,"credits":330,"badgeIds":["the-infinite-loop"],"skillXp":{"agentic_ai":55,"ai_ml_fundamentals":20}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-ai-agentic-ai-01', 1, 'maya', 'The evidence-checking pass did its job. It found records in our own archive that do not match their own checksums or timestamps. Quarantined, as of last night.'),
  ('mission-ai-agentic-ai-01', 2, 'maya', 'What it cannot do is tell us anything more about them. It flags. It does not investigate. That gap is what this Act closes.'),
  ('mission-ai-agentic-ai-01', 3, 'elena', 'Every tool we have built so far waits to be asked, does one thing, and stops. A tool call is a single request-response: give it input, get output, done. Nothing about it decides what happens next.'),
  ('mission-ai-agentic-ai-01', 4, 'elena', 'An agent is different. It is a system that can look at a result, decide for itself what to do with it, and choose its own next action -- including calling another tool, or the same one again, without being asked each time.'),
  ('mission-ai-agentic-ai-01', 5, 'noah', 'That difference is not academic for us. A poisoned archive means we cannot fully trust our own memory anymore. We need something that can form its own hypotheses about those records, check its own work, and decide what to look at next.'),
  ('mission-ai-agentic-ai-01', 6, 'maya', 'So this Act is not about building a bigger retriever. It is about building the first thing in Cipher Division that can actually investigate on its own. Start with the line between calling a tool and being an agent -- because everything after this depends on getting that line right.'),

  ('mission-ai-agentic-ai-02', 1, 'noah', 'Underneath every agent is one repeating cycle: the model gets the current situation, decides on an action, that action runs, the result comes back, and the model sees the whole thing again before deciding the next action.'),
  ('mission-ai-agentic-ai-02', 2, 'noah', 'That is the model loop. Not one call. A call, a result, appended to what the model can see, then another call -- until the model itself decides to stop instead of a person deciding for it.'),
  ('mission-ai-agentic-ai-02', 3, 'elena', 'The important part is what "seeing the whole thing again" means: every result from every prior step stays visible to the model on the next turn. That accumulated history is what lets it actually reason instead of guessing blind each time.'),

  ('mission-ai-agentic-ai-03', 1, 'elena', 'An agent only knows what a tool does from its description. Not from the code. Not from what you meant. From the words you gave it.'),
  ('mission-ai-agentic-ai-03', 2, 'byte', 'I have watched this go wrong in ops automation for years. Call a tool "search_records" with no detail on what it searches, what format it expects, or when it fails, and whatever calls it will guess -- badly, and confidently.'),
  ('mission-ai-agentic-ai-03', 3, 'elena', 'A good tool description states exactly what the tool does, what input it needs, what it returns, and what it cannot do. Vague enough to leave any of that out, and the model fills the gap with an assumption nobody approved.'),

  ('mission-ai-agentic-ai-04', 1, 'elena', 'ReAct interleaves two things that used to happen separately: reasoning about what to do, and actually doing it. Thought, then action, then observation, then thought again -- one continuous loop.'),
  ('mission-ai-agentic-ai-04', 2, 'noah', 'The thought step is the model narrating its own reasoning in plain terms before it acts -- "the checksum mismatch could mean corruption or tampering, checking the ingestion log first." Then it acts on that reasoning, observes the result, and reasons again.'),
  ('mission-ai-agentic-ai-04', 3, 'elena', 'Writing the reasoning out loud, every step, is not decoration. It is what makes the next action traceable instead of a black box -- which matters enormously once we point this at our own archive.'),

  ('mission-ai-agentic-ai-05', 1, 'noah', 'Not every branch in an agent belongs to the model. If a decision follows a fixed, known rule -- file type, record status, a simple threshold -- hard-code it. Do not spend a model call reasoning about something that was never actually in question.'),
  ('mission-ai-agentic-ai-05', 2, 'elena', 'Deterministic routing means the branch is decided by ordinary code: an if-statement, a lookup table, a status check. An LLM router, by contrast, asks the model itself to decide which path to take when the branch genuinely depends on judgment.'),
  ('mission-ai-agentic-ai-05', 3, 'noah', '"Is this record flagged quarantined" is deterministic -- read a field, branch on it. "Does this record''s content actually support the claim it makes" needs judgment. Mixing those up wastes model calls on one and shortchanges the other.'),

  ('mission-ai-agentic-ai-06', 1, 'elena', 'A planner/executor design splits the work in two. A planner looks at the whole task once and produces an ordered set of steps. An executor then carries each step out, one at a time, without re-planning the entire investigation every turn.'),
  ('mission-ai-agentic-ai-06', 2, 'noah', 'The planner can be a bigger, slower model since it only runs once or occasionally. The executor can be cheaper and faster since it is just carrying out a step it was already told to do.'),
  ('mission-ai-agentic-ai-06', 3, 'elena', 'For the archive investigation, a planner might decide the order: verify checksums, check the migration and correction logs, then cross-reference content. An executor just runs each of those, one after another.'),

  ('mission-ai-agentic-ai-07', 1, 'elena', 'A planner/executor design can carry out every step correctly and still produce a weak result, because nothing in that loop checks the quality of what came out.'),
  ('mission-ai-agentic-ai-07', 2, 'elena', 'Evaluator/optimizer adds that check back in: an evaluator scores the executor''s output against some standard, and if it falls short, an optimizer revises the approach and tries again -- a second pass judging the first.'),
  ('mission-ai-agentic-ai-07', 3, 'elena', 'This is the same instinct behind retrieval grading from Act 30, aimed at an agent''s own output instead of a retrieved document: do not just produce a result, judge it before it is treated as final.'),

  ('mission-ai-agentic-ai-08', 1, 'noah', 'Checking three unrelated archive records for tampering does not require checking them in order. Nothing about record two depends on what record one found.'),
  ('mission-ai-agentic-ai-08', 2, 'noah', 'Parallel work means firing off independent tool calls at the same time instead of waiting on each one before starting the next -- as long as none of them actually need each other''s results first.'),
  ('mission-ai-agentic-ai-08', 3, 'elena', 'The catch is knowing which steps are truly independent. Two checks that both write to the same quarantine list are not safe to run at the same time, no matter how unrelated the records look.'),

  ('mission-ai-agentic-ai-09', 1, 'elena', 'Without memory, an agent that already ruled out a migration as the explanation for record ai-arc-0447 has no way to know that on its next turn. It might check the exact same thing again.'),
  ('mission-ai-agentic-ai-09', 2, 'byte', 'Short-term memory is just what stays in the running conversation -- the steps taken so far, this investigation, this session. It disappears when the session ends.'),
  ('mission-ai-agentic-ai-09', 3, 'elena', 'Long-term memory persists across sessions -- written somewhere durable, so a fact learned today about a quarantined record is still known tomorrow, without re-deriving it from scratch.'),

  ('mission-ai-agentic-ai-10', 1, 'noah', 'Memory is content the agent chooses to keep. State is the structure the whole system runs on -- the current step, which records have been checked, what tools were already called, what has not been decided yet.'),
  ('mission-ai-agentic-ai-10', 2, 'noah', 'Every turn of the loop reads the current state, does something, and writes an updated state back. Lose track of state and the agent does not know where it actually is in the investigation, even with perfect memory of what it said earlier.'),
  ('mission-ai-agentic-ai-10', 3, 'elena', 'Good state design names exactly what gets tracked -- records_checked, current_hypothesis, pending_actions -- instead of leaving the agent to reconstruct its own progress from a wall of prior text each time.'),

  ('mission-ai-agentic-ai-11', 1, 'noah', 'A loop with no exit is not patient. It is broken. Every agent needs a way to decide it is done -- a termination condition -- and a hard ceiling on effort it can never cross, a budget.'),
  ('mission-ai-agentic-ai-11', 2, 'elena', 'A termination condition is a rule for success: the claim is now supported by evidence, the record is confirmed tampered, the question is answered. A budget is a rule against runaway cost: a maximum number of steps, tool calls, or tokens, regardless of whether the model feels finished.'),
  ('mission-ai-agentic-ai-11', 3, 'noah', 'And when neither one resolves things -- the evidence stays ambiguous and the budget runs out -- the correct behavior is not to keep guessing. It is to escalate to a human and say so plainly.'),

  ('mission-ai-agentic-ai-12', 1, 'maya', 'Cipher Division''s first real investigative agent went live overnight, pointed at the two quarantined records. Characterize what happened to them. That was the whole task.'),
  ('mission-ai-agentic-ai-12', 2, 'noah', 'It has been running for six hours. Still marked in progress. No conclusion, no escalation, nothing written to the case file. I am pulling the trace log now.'),
  ('mission-ai-agentic-ai-12', 3, 'elena', 'This does not look like six hours of investigation. It looks like the same handful of steps, over and over. Something in here never actually moved forward.'),
  ('mission-ai-agentic-ai-12', 4, 'noah', 'Walk the trace with me. Whatever it kept doing, and whatever it kept failing to do about it, is sitting right there in the log.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-ai-agentic-ai-01-o1', 'mission-ai-agentic-ai-01', 1, 'Draw the line', 'State the actual difference between a single tool call and an agent.'),
  ('mission-ai-agentic-ai-01-o2', 'mission-ai-agentic-ai-01', 2, 'Sort the behavior', 'Sort each described system into tool call or agent.'),

  ('mission-ai-agentic-ai-02-o1', 'mission-ai-agentic-ai-02', 1, 'Name the loop', 'Identify what actually repeats in the model loop.'),
  ('mission-ai-agentic-ai-02-o2', 'mission-ai-agentic-ai-02', 2, 'Order the cycle', 'Order the stages of one turn of the model loop.'),

  ('mission-ai-agentic-ai-03-o1', 'mission-ai-agentic-ai-03', 1, 'Judge the description', 'Pick the tool description that actually gives an agent what it needs.'),
  ('mission-ai-agentic-ai-03-o2', 'mission-ai-agentic-ai-03', 2, 'Diagnose the failure', 'Find the evidence that explains why an agent misused a tool.'),

  ('mission-ai-agentic-ai-04-o1', 'mission-ai-agentic-ai-04', 1, 'Define ReAct', 'State what ReAct interleaves.'),
  ('mission-ai-agentic-ai-04-o2', 'mission-ai-agentic-ai-04', 2, 'Order the loop', 'Order one cycle of thought, action, and observation.'),

  ('mission-ai-agentic-ai-05-o1', 'mission-ai-agentic-ai-05', 1, 'Tell the routers apart', 'State the difference between deterministic routing and an LLM router.'),
  ('mission-ai-agentic-ai-05-o2', 'mission-ai-agentic-ai-05', 2, 'Route each decision', 'Sort each branching decision into deterministic routing or LLM routing.'),

  ('mission-ai-agentic-ai-06-o1', 'mission-ai-agentic-ai-06', 1, 'Split the roles', 'State what a planner does that an executor does not.'),
  ('mission-ai-agentic-ai-06-o2', 'mission-ai-agentic-ai-06', 2, 'Assign the step', 'Sort each investigation step into planner or executor.'),

  ('mission-ai-agentic-ai-07-o1', 'mission-ai-agentic-ai-07', 1, 'Define the pass', 'State what an evaluator checks that a planner/executor loop alone does not.'),
  ('mission-ai-agentic-ai-07-o2', 'mission-ai-agentic-ai-07', 2, 'Order the cycle', 'Order one cycle of the evaluator/optimizer pattern.'),

  ('mission-ai-agentic-ai-08-o1', 'mission-ai-agentic-ai-08', 1, 'Spot true independence', 'Decide which set of steps is actually safe to run in parallel.'),
  ('mission-ai-agentic-ai-08-o2', 'mission-ai-agentic-ai-08', 2, 'Name the risk', 'State the real danger of running dependent steps in parallel.'),

  ('mission-ai-agentic-ai-09-o1', 'mission-ai-agentic-ai-09', 1, 'Tell the memory types apart', 'State the difference between short-term and long-term agent memory.'),
  ('mission-ai-agentic-ai-09-o2', 'mission-ai-agentic-ai-09', 2, 'Diagnose the repeat', 'Find the evidence explaining why an agent redid work it had already done.'),

  ('mission-ai-agentic-ai-10-o1', 'mission-ai-agentic-ai-10', 1, 'Separate memory from state', 'State the difference between an agent''s memory and its state.'),
  ('mission-ai-agentic-ai-10-o2', 'mission-ai-agentic-ai-10', 2, 'Design the state', 'Match each state field to what it should actually track.'),

  ('mission-ai-agentic-ai-11-o1', 'mission-ai-agentic-ai-11', 1, 'Tell the safeguards apart', 'State the difference between a termination condition and a budget.'),
  ('mission-ai-agentic-ai-11-o2', 'mission-ai-agentic-ai-11', 2, 'Handle the unresolved case', 'Decide the correct behavior when neither the termination condition nor the budget resolves things.'),

  ('mission-ai-agentic-ai-12-o1', 'mission-ai-agentic-ai-12', 1, 'Read the trace', 'Find the evidence showing the agent repeated the same tool call with no new information gained.'),
  ('mission-ai-agentic-ai-12-o2', 'mission-ai-agentic-ai-12', 2, 'Diagnose the root cause', 'Identify what is actually missing from the agent''s design that let this happen.'),
  ('mission-ai-agentic-ai-12-o3', 'mission-ai-agentic-ai-12', 3, 'Choose the fix', 'Choose the correct engineered fix for an agent that cannot resolve ambiguous evidence on its own.'),
  ('mission-ai-agentic-ai-12-o4', 'mission-ai-agentic-ai-12', 4, 'State the conclusion', 'Having read the trace, diagnosed the cause, and chosen the fix, state what went wrong and how to prevent it.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-ai-agentic-ai-01-o1-c1', 'mission-ai-agentic-ai-01-o1', 1, 'multiple_choice', 'What is the actual difference between a single tool call and an agent?', '{"question":"What is the actual difference between a single tool call and an agent?","options":[{"id":"a","text":"An agent uses a bigger model, a tool call uses a smaller one"},{"id":"b","text":"A tool call is one request and one response; an agent decides, on its own, what action to take next based on the result it just saw"},{"id":"c","text":"There is no real difference, the terms are interchangeable"},{"id":"d","text":"An agent never uses tools at all"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-agentic-ai-01-o2-c1', 'mission-ai-agentic-ai-01-o2', 1, 'drag_and_drop', 'Sort each described system into tool call or agent.', '{"items":[{"id":"i1","text":"A function that takes a record ID and returns its checksum, once, when called"},{"id":"i2","text":"A system that checks a checksum, decides for itself the mismatch is worth investigating further, and chooses to pull the migration log next without being asked"},{"id":"i3","text":"A weather lookup that returns today''s forecast for a given city"},{"id":"i4","text":"A system that reads an ambiguous result, decides more evidence is needed, and picks which log to check next on its own"}],"targets":[{"id":"tool","label":"Single tool call"},{"id":"agent","label":"Agent"}]}'::jsonb, '{"correctMapping":{"i1":"tool","i2":"agent","i3":"tool","i4":"agent"}}'::jsonb),

  ('mission-ai-agentic-ai-02-o1-c1', 'mission-ai-agentic-ai-02-o1', 1, 'multiple_choice', 'In the model loop, what actually repeats?', '{"question":"In the model loop, what actually repeats?","options":[{"id":"a","text":"The same fixed prompt, sent over and over with no new information"},{"id":"b","text":"The model seeing the current situation including all prior results, choosing an action, and getting a new result appended before it decides again"},{"id":"c","text":"The training process, re-run after every tool call"},{"id":"d","text":"A human manually re-approving each step before it can continue"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-agentic-ai-02-o2-c1', 'mission-ai-agentic-ai-02-o2', 1, 'interactive_diagram', 'Order the stages of one turn of the model loop.', '{"diagramId":"model-loop","hotspots":[{"id":"h1","label":"Model sees the current situation and full history so far","explanation":"Every prior action and result is still visible before the model decides anything."},{"id":"h2","label":"Model decides on the next action","explanation":"Given everything it can see, the model chooses what to do next."},{"id":"h3","label":"Action executes","explanation":"The chosen tool or step actually runs."},{"id":"h4","label":"Result is appended to what the model can see","explanation":"The outcome becomes part of the history available on the next turn."},{"id":"h5","label":"Model decides whether to continue or stop","explanation":"With the new result in view, the model chooses to act again or conclude."}],"task":"Order the stages of one turn of the model loop from first to last."}'::jsonb, '{"correctOrderIds":["h1","h2","h3","h4","h5"]}'::jsonb),

  ('mission-ai-agentic-ai-03-o1-c1', 'mission-ai-agentic-ai-03-o1', 1, 'multiple_choice', 'Which tool description actually gives an agent what it needs to use the tool correctly?', '{"question":"Which tool description actually gives an agent what it needs to use the tool correctly?","options":[{"id":"a","text":"check_record: checks a record"},{"id":"b","text":"check_record(record_id: string): verifies a single archive record''s content hash against its ingestion-time checksum; returns match or mismatch plus the recorded and current hash; fails if record_id does not exist"},{"id":"c","text":"A tool for records"},{"id":"d","text":"check_record: use this when needed"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-agentic-ai-03-o2-c1', 'mission-ai-agentic-ai-03-o2', 1, 'investigation', 'An agent called quarantine_record on a record that only needed a second checksum check, not quarantine. Which evidence explains the misuse?', '{"evidence":[{"id":"e1","label":"Tool registry","detail":"quarantine_record is described only as: quarantine a record. No mention of when it should be used or what it does to retrieval."},{"id":"e2","label":"Agent trace","detail":"Model reasoned: mismatch found, quarantine_record sounds closest to relevant, calling it."},{"id":"e3","label":"Server log","detail":"The tool server responded within normal latency"}],"question":"Which evidence explains why the agent misused the tool?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-agentic-ai-04-o1-c1', 'mission-ai-agentic-ai-04-o1', 1, 'multiple_choice', 'ReAct interleaves which two things into one running loop?', '{"question":"ReAct interleaves which two things into one running loop?","options":[{"id":"a","text":"Training and inference"},{"id":"b","text":"Explicit, narrated reasoning about what to do, and actually taking an action, repeated in sequence"},{"id":"c","text":"Retrieval and generation"},{"id":"d","text":"Planning and evaluation"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-agentic-ai-04-o2-c1', 'mission-ai-agentic-ai-04-o2', 1, 'interactive_diagram', 'Order one cycle of the ReAct pattern.', '{"diagramId":"react-loop","hotspots":[{"id":"h1","label":"Thought: reason about what to do next, in plain terms","explanation":"The model narrates its own reasoning before acting."},{"id":"h2","label":"Action: call a tool based on that reasoning","explanation":"The reasoning is turned into a concrete tool call."},{"id":"h3","label":"Observation: read the result of the action","explanation":"The outcome of the action is examined."},{"id":"h4","label":"Thought: reason again, now including the new observation","explanation":"The cycle repeats with the new information folded in."}],"task":"Order one cycle of thought, action, and observation."}'::jsonb, '{"correctOrderIds":["h1","h2","h3","h4"]}'::jsonb),

  ('mission-ai-agentic-ai-05-o1-c1', 'mission-ai-agentic-ai-05-o1', 1, 'multiple_choice', 'How does deterministic routing differ from an LLM router?', '{"question":"How does deterministic routing differ from an LLM router?","options":[{"id":"a","text":"Deterministic routing uses ordinary code and a fixed rule to decide the branch; an LLM router asks the model to decide when the branch genuinely needs judgment"},{"id":"b","text":"They are the same thing with different names"},{"id":"c","text":"Deterministic routing is always slower than an LLM router"},{"id":"d","text":"An LLM router never calls a model at all"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-agentic-ai-05-o2-c1', 'mission-ai-agentic-ai-05-o2', 1, 'drag_and_drop', 'Sort each branching decision into deterministic routing or LLM routing.', '{"items":[{"id":"i1","text":"Is this record already marked quarantined in its metadata field"},{"id":"i2","text":"Does this document''s claim actually hold up against the rest of the archive"},{"id":"i3","text":"Is the checksum mismatch above or below a fixed numeric threshold"},{"id":"i4","text":"Given ambiguous evidence, should the investigation escalate to a human"}],"targets":[{"id":"deterministic","label":"Deterministic routing"},{"id":"llm","label":"LLM router"}]}'::jsonb, '{"correctMapping":{"i1":"deterministic","i2":"llm","i3":"deterministic","i4":"llm"}}'::jsonb),

  ('mission-ai-agentic-ai-06-o1-c1', 'mission-ai-agentic-ai-06-o1', 1, 'multiple_choice', 'In a planner/executor design, what does the planner do that the executor does not?', '{"question":"In a planner/executor design, what does the planner do that the executor does not?","options":[{"id":"a","text":"The planner produces an ordered set of steps for the whole task; the executor carries out each step without re-planning the entire task every turn"},{"id":"b","text":"The planner only writes code, the executor only reads it"},{"id":"c","text":"The planner runs after the executor finishes"},{"id":"d","text":"There is no difference, they always run as the same call"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-agentic-ai-06-o2-c1', 'mission-ai-agentic-ai-06-o2', 1, 'drag_and_drop', 'Sort each investigation step into planner or executor.', '{"items":[{"id":"i1","text":"Deciding the overall order: verify checksums, then check logs, then cross-reference content"},{"id":"i2","text":"Actually calling verify_checksum on record ai-arc-0447"},{"id":"i3","text":"Actually calling check_migration_log for the flagged records"},{"id":"i4","text":"Deciding that cross-referencing content should come last because it depends on the log results"}],"targets":[{"id":"planner","label":"Planner"},{"id":"executor","label":"Executor"}]}'::jsonb, '{"correctMapping":{"i1":"planner","i2":"executor","i3":"executor","i4":"planner"}}'::jsonb),

  ('mission-ai-agentic-ai-07-o1-c1', 'mission-ai-agentic-ai-07-o1', 1, 'multiple_choice', 'What does an evaluator/optimizer pass check that a plain planner/executor loop does not?', '{"question":"What does an evaluator/optimizer pass check that a plain planner/executor loop does not?","options":[{"id":"a","text":"Whether the executor''s output actually meets a quality standard, revising the approach if it falls short"},{"id":"b","text":"Whether the tools are online"},{"id":"c","text":"Whether the planner used enough steps"},{"id":"d","text":"Nothing, it duplicates the executor exactly"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-agentic-ai-07-o2-c1', 'mission-ai-agentic-ai-07-o2', 1, 'interactive_diagram', 'Order one cycle of the evaluator/optimizer pattern.', '{"diagramId":"evaluator-optimizer-loop","hotspots":[{"id":"h1","label":"Executor produces an output","explanation":"A step is carried out and produces a result."},{"id":"h2","label":"Evaluator scores the output against a standard","explanation":"A separate pass judges whether the result is actually good enough."},{"id":"h3","label":"If it falls short, optimizer revises the approach","explanation":"A weak result triggers a revision rather than being accepted as-is."},{"id":"h4","label":"Executor tries again with the revised approach","explanation":"The step reruns using what the optimizer changed."}],"task":"Order one cycle of the evaluator/optimizer pattern."}'::jsonb, '{"correctOrderIds":["h1","h2","h3","h4"]}'::jsonb),

  ('mission-ai-agentic-ai-08-o1-c1', 'mission-ai-agentic-ai-08-o1', 1, 'multiple_choice', 'Which set of steps is actually safe to run in parallel?', '{"question":"Which set of steps is actually safe to run in parallel?","options":[{"id":"a","text":"Verifying the checksum of record ai-arc-0447 and verifying the checksum of unrelated record ai-arc-0512 at the same time"},{"id":"b","text":"Reading the current quarantine list, then writing a new entry to it, at the same time"},{"id":"c","text":"Checking a record''s migration log and then using that log''s result to decide the next query, at the same time"},{"id":"d","text":"Two steps where the second explicitly needs the first step''s output"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-agentic-ai-08-o2-c1', 'mission-ai-agentic-ai-08-o2', 1, 'multiple_choice', 'What is the real danger of running two dependent steps in parallel?', '{"question":"What is the real danger of running two dependent steps in parallel?","options":[{"id":"a","text":"It uses slightly more electricity"},{"id":"b","text":"One step may run using stale or missing information from the other, producing a wrong or inconsistent result, such as two writes racing to the same list"},{"id":"c","text":"Nothing, parallel execution is always safe"},{"id":"d","text":"It makes the tool descriptions invalid"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-agentic-ai-09-o1-c1', 'mission-ai-agentic-ai-09-o1', 1, 'multiple_choice', 'What is the difference between short-term and long-term agent memory?', '{"question":"What is the difference between short-term and long-term agent memory?","options":[{"id":"a","text":"Short-term memory lives only within the current running session and disappears after; long-term memory is written somewhere durable and persists across sessions"},{"id":"b","text":"Short-term memory is stored in the model''s parameters permanently"},{"id":"c","text":"There is no real difference"},{"id":"d","text":"Long-term memory only stores tool descriptions"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-agentic-ai-09-o2-c1', 'mission-ai-agentic-ai-09-o2', 1, 'investigation', 'An agent re-checked whether ai-arc-0447''s discrepancy had a migration on file, despite ruling that out yesterday. Which evidence explains the repeat?', '{"evidence":[{"id":"e1","label":"Session log","detail":"Yesterday''s conclusion, that no migration explains ai-arc-0447, was never written to durable long-term storage before the session ended"},{"id":"e2","label":"Tool registry","detail":"check_migration_log is described accurately and functioning normally"},{"id":"e3","label":"Facilities log","detail":"Cipher Labs power draw is within normal range"}],"question":"Which evidence explains why the agent redid work it had already done?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-agentic-ai-10-o1-c1', 'mission-ai-agentic-ai-10-o1', 1, 'multiple_choice', 'How does an agent''s state differ from its memory?', '{"question":"How does an agent''s state differ from its memory?","options":[{"id":"a","text":"Memory is content the agent chooses to retain; state is the structured tracking of exactly where the system currently stands -- current step, records checked, pending actions"},{"id":"b","text":"State and memory are always the same field"},{"id":"c","text":"State only exists after an agent finishes running"},{"id":"d","text":"Memory tracks pending actions, state tracks nothing"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-agentic-ai-10-o2-c1', 'mission-ai-agentic-ai-10-o2', 1, 'drag_and_drop', 'Match each state field to what it should actually track.', '{"items":[{"id":"i1","text":"records_checked"},{"id":"i2","text":"current_hypothesis"},{"id":"i3","text":"pending_actions"},{"id":"i4","text":"budget_remaining"}],"targets":[{"id":"t1","label":"Which archive records have already been examined"},{"id":"t2","label":"The agent''s current best explanation for the discrepancy"},{"id":"t3","label":"The next steps queued but not yet carried out"},{"id":"t4","label":"How much step or cost budget is left before the hard ceiling"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),

  ('mission-ai-agentic-ai-11-o1-c1', 'mission-ai-agentic-ai-11-o1', 1, 'multiple_choice', 'What is the difference between a termination condition and a budget?', '{"question":"What is the difference between a termination condition and a budget?","options":[{"id":"a","text":"A termination condition is a rule for recognizing success or completion; a budget is a hard ceiling on effort, such as steps or tool calls, regardless of whether the model feels done"},{"id":"b","text":"They are the same safeguard under two names"},{"id":"c","text":"A budget only applies to token count, never to steps"},{"id":"d","text":"A termination condition is optional and a budget is not needed if it exists"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-agentic-ai-11-o2-c1', 'mission-ai-agentic-ai-11-o2', 1, 'multiple_choice', 'The evidence stays ambiguous and the step budget has run out. What is the correct behavior?', '{"question":"The evidence stays ambiguous and the step budget has run out. What is the correct behavior?","options":[{"id":"a","text":"Keep running past the budget until the model feels confident"},{"id":"b","text":"Escalate to a human with a clear statement that the evidence was insufficient to conclude, rather than guessing or looping further"},{"id":"c","text":"Pick an answer at random and report it as the conclusion"},{"id":"d","text":"Silently stop with no record of what happened"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-agentic-ai-12-o1-c1', 'mission-ai-agentic-ai-12-o1', 1, 'investigation', 'Which evidence shows the agent repeated the same tool call with no new information gained?', '{"evidence":[{"id":"e1","label":"Trace log (steps 1-4)","detail":"Called verify_checksum on ai-arc-0447, got mismatch, confirmed already known, no new detail"},{"id":"e2","label":"Trace log (steps 5-118)","detail":"Called verify_checksum on ai-arc-0447 again, and again, over 100 times, each call returning the identical mismatch result already seen at step 1"},{"id":"e3","label":"Tool registry","detail":"verify_checksum is accurately described and functioning correctly on every call"},{"id":"e4","label":"Facilities log","detail":"Cipher Labs power draw is within normal range"}],"question":"Which evidence shows the agent repeated the same tool call with no new information gained?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-ai-agentic-ai-12-o2-c1', 'mission-ai-agentic-ai-12-o2', 1, 'investigation', 'What is actually missing from the agent''s design that let it loop for six hours?', '{"evidence":[{"id":"e1","label":"Agent config","detail":"No termination condition defined for what counts as a resolved investigation, and no maximum step or cost budget set"},{"id":"e2","label":"Trace reasoning","detail":"At each repeat, the model reasoned: result is still ambiguous, checking again to be sure"},{"id":"e3","label":"Tool registry","detail":"verify_checksum works correctly and is well-described"}],"question":"What is actually missing from the agent''s design that let it loop for six hours?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-agentic-ai-12-o3-c1', 'mission-ai-agentic-ai-12-o3', 1, 'multiple_choice', 'Given an agent that loops indefinitely on ambiguous, unchanging evidence with no defined stopping point, what is the correct engineered fix?', '{"question":"Given an agent that loops indefinitely on ambiguous, unchanging evidence with no defined stopping point, what is the correct engineered fix?","options":[{"id":"a","text":"Add a better tool description for verify_checksum"},{"id":"b","text":"Define a termination condition for what counts as resolved, set a hard step or cost budget, and add an explicit escalate-to-human fallback for when the budget is exhausted without resolution"},{"id":"c","text":"Switch to a larger underlying model so it reasons better"},{"id":"d","text":"Remove verify_checksum from the tool registry entirely"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-agentic-ai-12-o4-c1', 'mission-ai-agentic-ai-12-o4', 1, 'boss_encounter', 'Having read the trace, diagnosed the missing safeguard, and chosen the fix, state what happened and how to prevent it, in one sentence.', '{"stages":[{"objectiveRef":"mission-ai-agentic-ai-12-o1","label":"Read the trace"},{"objectiveRef":"mission-ai-agentic-ai-12-o2","label":"Diagnose the root cause"},{"objectiveRef":"mission-ai-agentic-ai-12-o3","label":"Choose the fix"}],"task":"State the conclusion in one sentence: the agent looped for six hours re-running the same checksum call on ambiguous evidence because it had no termination condition, no step budget, and no escalation fallback -- and all three need to be added before it runs again."}'::jsonb, '{"requiredObjectiveIds":["mission-ai-agentic-ai-12-o1","mission-ai-agentic-ai-12-o2","mission-ai-agentic-ai-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-ai-agentic-ai-01-o1-c1', 'orientation', 'Ask whether the system decides its own next step, or just answers once and stops.', 10, 1),
  ('mission-ai-agentic-ai-01-o1-c1', 'solution', 'A tool call is a single request and response. An agent decides, on its own, what to do next based on the result it just saw.', 20, 2),
  ('mission-ai-agentic-ai-01-o2-c1', 'orientation', 'A tool call never chooses its own next action. An agent always does.', 10, 1),
  ('mission-ai-agentic-ai-01-o2-c1', 'solution', 'Tool call: the plain checksum lookup, the plain weather lookup. Agent: anything that decides for itself what to check next based on what it just found.', 20, 2),

  ('mission-ai-agentic-ai-02-o1-c1', 'orientation', 'Focus on what stays visible to the model between steps, not just what happens once.', 10, 1),
  ('mission-ai-agentic-ai-02-o1-c1', 'solution', 'The model sees the accumulated situation including every prior result, chooses an action, and gets the new result appended before deciding again.', 20, 2),
  ('mission-ai-agentic-ai-02-o2-c1', 'orientation', 'Nothing can execute before the model has actually chosen an action.', 10, 1),
  ('mission-ai-agentic-ai-02-o2-c1', 'concept', 'A decision to continue or stop can only happen after the new result has been folded back into what the model can see.', 20, 2),
  ('mission-ai-agentic-ai-02-o2-c1', 'solution', 'See the situation and history, decide the action, execute it, append the result, then decide whether to continue or stop.', 30, 3),

  ('mission-ai-agentic-ai-03-o1-c1', 'orientation', 'A good description tells the agent what the tool needs, what it returns, and when it fails.', 10, 1),
  ('mission-ai-agentic-ai-03-o1-c1', 'solution', 'Only the checksum description spells out the input, the return values, and the failure case -- everything else forces the agent to guess.', 20, 2),
  ('mission-ai-agentic-ai-03-o2-c1', 'orientation', 'The agent did not misread the situation. It misread the tool.', 10, 1),
  ('mission-ai-agentic-ai-03-o2-c1', 'solution', 'e1: the tool registry never explained when quarantine_record should be used or what it actually does, so the agent guessed from the name alone.', 20, 2),

  ('mission-ai-agentic-ai-04-o1-c1', 'orientation', 'Think about what gets written out loud before an action happens.', 10, 1),
  ('mission-ai-agentic-ai-04-o1-c1', 'solution', 'ReAct interleaves explicit, narrated reasoning with actually taking an action, in a repeating cycle.', 20, 2),
  ('mission-ai-agentic-ai-04-o2-c1', 'orientation', 'Nothing can be observed before an action has actually run.', 10, 1),
  ('mission-ai-agentic-ai-04-o2-c1', 'solution', 'Thought, action, observation, then thought again with the new observation folded in.', 20, 2),

  ('mission-ai-agentic-ai-05-o1-c1', 'orientation', 'Ask which side needs judgment and which side is just checking a fixed rule.', 10, 1),
  ('mission-ai-agentic-ai-05-o1-c1', 'solution', 'Deterministic routing uses plain code and a fixed rule. An LLM router asks the model to decide when the branch genuinely needs judgment.', 20, 2),
  ('mission-ai-agentic-ai-05-o2-c1', 'orientation', 'A status field or a numeric threshold does not need a model to read it.', 10, 1),
  ('mission-ai-agentic-ai-05-o2-c1', 'solution', 'Deterministic: the metadata flag check and the fixed threshold. LLM router: judging whether a claim holds up, and deciding whether ambiguity should escalate.', 20, 2),

  ('mission-ai-agentic-ai-06-o1-c1', 'orientation', 'One role decides the whole order once. The other role carries out one step at a time.', 10, 1),
  ('mission-ai-agentic-ai-06-o1-c1', 'solution', 'The planner produces the ordered steps for the whole task; the executor carries each one out without re-planning from scratch every turn.', 20, 2),
  ('mission-ai-agentic-ai-06-o2-c1', 'orientation', 'Ask whether the item decides ordering, or actually performs a specific action.', 10, 1),
  ('mission-ai-agentic-ai-06-o2-c1', 'solution', 'Planner: deciding overall order and dependency-based sequencing. Executor: the actual verify_checksum and check_migration_log calls.', 20, 2),

  ('mission-ai-agentic-ai-07-o1-c1', 'orientation', 'A planner/executor loop can complete every step without anything judging how well it was done.', 10, 1),
  ('mission-ai-agentic-ai-07-o1-c1', 'solution', 'An evaluator scores the output against a real standard, and an optimizer revises the approach if it falls short.', 20, 2),
  ('mission-ai-agentic-ai-07-o2-c1', 'orientation', 'Nothing can be scored before an output actually exists.', 10, 1),
  ('mission-ai-agentic-ai-07-o2-c1', 'solution', 'Executor produces output, evaluator scores it, optimizer revises if it falls short, executor tries again.', 20, 2),

  ('mission-ai-agentic-ai-08-o1-c1', 'orientation', 'True independence means neither step reads or writes anything the other one touches.', 10, 1),
  ('mission-ai-agentic-ai-08-o1-c1', 'solution', 'Verifying two unrelated records'' checksums at the same time is safe -- neither result depends on or writes to the other.', 20, 2),
  ('mission-ai-agentic-ai-08-o2-c1', 'orientation', 'Think about what happens when two steps touch the exact same data at the exact same time.', 10, 1),
  ('mission-ai-agentic-ai-08-o2-c1', 'solution', 'A dependent step run in parallel may act on stale or missing data from the other, producing a wrong result or a race condition like two writes colliding.', 20, 2),

  ('mission-ai-agentic-ai-09-o1-c1', 'orientation', 'One kind of memory survives the session ending. The other does not.', 10, 1),
  ('mission-ai-agentic-ai-09-o1-c1', 'solution', 'Short-term memory disappears when the session ends. Long-term memory is written durably and persists across sessions.', 20, 2),
  ('mission-ai-agentic-ai-09-o2-c1', 'orientation', 'The tools worked fine. Ask what happened to yesterday''s conclusion after the session closed.', 10, 1),
  ('mission-ai-agentic-ai-09-o2-c1', 'solution', 'e1: yesterday''s ruling-out of a migration was never written to durable storage, so it was gone once the session ended, and the agent had to redo it.', 20, 2),

  ('mission-ai-agentic-ai-10-o1-c1', 'orientation', 'One is content the agent remembers. The other is the structure tracking exactly where things stand right now.', 10, 1),
  ('mission-ai-agentic-ai-10-o1-c1', 'solution', 'Memory is retained content. State is the structured tracking of the current step, records checked, and pending actions.', 20, 2),
  ('mission-ai-agentic-ai-10-o2-c1', 'orientation', 'Match each field name to the one fact it is clearly meant to hold.', 10, 1),
  ('mission-ai-agentic-ai-10-o2-c1', 'solution', 'records_checked tracks what has been examined, current_hypothesis tracks the leading explanation, pending_actions tracks the queue, budget_remaining tracks effort left.', 20, 2),

  ('mission-ai-agentic-ai-11-o1-c1', 'orientation', 'One safeguard defines success. The other defines a hard limit regardless of success.', 10, 1),
  ('mission-ai-agentic-ai-11-o1-c1', 'solution', 'A termination condition recognizes when the task is actually done. A budget is a hard ceiling on effort no matter how the model feels.', 20, 2),
  ('mission-ai-agentic-ai-11-o2-c1', 'orientation', 'Running past a budget defeats the entire point of having one.', 10, 1),
  ('mission-ai-agentic-ai-11-o2-c1', 'solution', 'Escalate to a human with a clear statement that the evidence was insufficient, instead of guessing or continuing past the budget.', 20, 2),

  ('mission-ai-agentic-ai-12-o1-c1', 'orientation', 'Most of the trace is just one call, over and over, with an identical result each time.', 10, 1),
  ('mission-ai-agentic-ai-12-o1-c1', 'concept', 'A working tool returning the same correct result repeatedly is not evidence of a bug in the tool -- it is evidence of a loop with nowhere to go.', 20, 2),
  ('mission-ai-agentic-ai-12-o1-c1', 'solution', 'e2: verify_checksum was called on the same record over 100 times, each call returning the exact same mismatch already known from step one.', 30, 3),
  ('mission-ai-agentic-ai-12-o2-c1', 'orientation', 'The tool worked correctly every time. The problem is not the tool.', 10, 1),
  ('mission-ai-agentic-ai-12-o2-c1', 'solution', 'e1: no termination condition and no step or cost budget were ever defined, so the agent had no way to decide it was done.', 20, 2),
  ('mission-ai-agentic-ai-12-o3-c1', 'orientation', 'The fix targets the missing safeguard, not the tool or the model size.', 10, 1),
  ('mission-ai-agentic-ai-12-o3-c1', 'solution', 'Define a termination condition, set a hard step or cost budget, and add an explicit escalate-to-human fallback for unresolved ambiguity.', 20, 2),
  ('mission-ai-agentic-ai-12-o4-c1', 'orientation', 'Combine what the trace showed, what was missing, and what the fix actually adds.', 15, 1),
  ('mission-ai-agentic-ai-12-o4-c1', 'solution', 'The agent looped for six hours re-running the same checksum call on unchanging, ambiguous evidence because it had no termination condition, no budget, and no escalation path -- all three now need to be built in.', 25, 2);
